//go:build amd64

package floats

// Horner and Clenshaw kernels generated by go-asmgen (polyval_amd64_gen.go) into
// polyval_amd64.s: plain multiplies, adds and subtracts, no VFMADD. The callers
// pass dst and x sliced to the same length n >= 1; the Chebval kernels require
// len(c) >= 2, the Polyval kernels len(c) >= 1. None keeps a pointer.
//
//go:noescape
func polyvalAVX2(dst, x, c []float64)

//go:noescape
func chebvalAVX2(dst, x, c []float64)

//go:noescape
func polyvalSSE2(dst, x, c []float64)

//go:noescape
func chebvalSSE2(dst, x, c []float64)

func polyvalKernel(dst, x, c []float64) {
	if hasAVX2FMA {
		polyvalAVX2(dst, x, c)
		return
	}
	polyvalSSE2(dst, x, c)
}

func chebvalKernel(dst, x, c []float64) {
	if hasAVX2FMA {
		chebvalAVX2(dst, x, c)
		return
	}
	chebvalSSE2(dst, x, c)
}
